E,KAAQ;IACtD,YAAY,GAAG,CAAC;IAChB,cAAc,CAAC,IAAI,GAAG;AACxB;AAEO,SAAS;IACd,IAAI;QACF,KAAK,IAAI,OAAO,YACd,aAAa,OAAO,CAAC,KAAK,KAAK,SAAS,CAAC,cAAc,CAAC,IAAI;QAE9D,YAAY,KAAK;IACnB,EAAE,OAAO,GAAG;QACV,IAAI,CAAC,wBAAwB;YAC3B,yBAAyB;YACzB,CAAA,GAAA,YAAK,AAAD,EAAE,CAAC,gBAAgB,EAAG,GAAa,SAAS;QAClD;QACA,QAAQ,IAAI,CAAC;IACf;AACF;AAEA,YAAY,IAAM,uCAAuC;AAElD,SAAS;IACd,OAAO,gBAAgB,2BAA2B;AACpD;AAEO,SAAS;IACd,OAAO,KAAK,GAAG,CAAC,GAAG,gBAAgB,aAAa,MAAM;AACxD;AAEO,SAAS;IACd,OAAO;AACT;AAEO,SAAS;IACd,gBAAgB,aAAa,AAAC,CAAA,gBAAgB,aAAa,KAAK,CAAA,IAAK;AACvE;AAEA,IAAI,QAAQ;AAEL,eAAe;IACpB,IAAI,OAAO;IACX,QAAQ;IACR,IAAI,CAAC,UAAU,OAAO,EAAE;IACxB,IAAI,CAAC,UAAU,OAAO,CAAC,OAAO,EAAE;IAChC,IAAI,CAAC,UAAU,OAAO,CAAC,SAAS,EAAE;IAClC,IAAI,MAAM,UAAU,OAAO,CAAC,SAAS,IACnC;IAEF,MAAM,aAAa,MAAM,UAAU,OAAO,CAAC,OAAO;IAClD,IAAI,CAAC,YACH,QAAQ,IAAI,CAAC;AAEjB;;;;;AC9EA,wDAAgB;AAIhB,8CAAgB;AAPhB;;AAEA,MAAM,cAAc,CAAA,GAAA,+BAAY,AAAD;AACxB,SAAS,mBAAmB,KAAe;IAChD,OAAO,WAAW,CAAC,SAAS,MAAM,IAAI,IAAI,YAAY,MAAM,CAAC;AAC/D;AAEO,SAAS,SAAS,MAAc;IACrC,IAAI,OAAO;IACX,IAAK,IAAI,IAAI,GAAG,IAAI,OAAO,MAAM,EAAE,IAAK;QACtC,IAAI,OAAO,OAAO,UAAU,CAAC;QAC7B,OAAO,AAAC,CAAA,QAAQ,CAAA,IAAK,OAAO;QAC5B,OAAO,OAAO,MAAM,2BAA2B;IACjD;IACA,OAAO,KAAK,GAAG,CAAC;AAClB;;;ACjBA,OAAO,OAAO,GAAG,KAAK,KAAK,CAAC;;;ACA5B,OAAO,OAAO,GAAG,KAAK,KAAK,CAAC;;;;;mDCEf;qDAWA;AAbb;AAEO,MAAM,gBAA8C;IACzD,QAAQ,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IAChB,SAAS,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IACjB,SAAS,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IACjB,YAAY,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IACpB,OAAO,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IACf,UAAU,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IAClB,OAAO,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IACf,WAAW,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;AACrB;AAEO,MAAM,kBAAgD;IAC3D,QAAQ,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IAChB,SAAS,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IACjB,SAAS,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IACjB,YAAY,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IACpB,OAAO,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IACf,UAAU,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IAClB,OAAO,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;IACf,WAAW,IAAM,CAAA,GAAA,OAAC,AAAD,EAAE;AACrB","sources":["src/level_editor/levels_editor.tsx","node_modules/react/jsx-dev-runtime.js","node_modules/react/cjs/react-jsx-dev-runtime.development.js","node_modules/react/index.js","node_modules/react/cjs/react.development.js","node_modules/process/browser.js","src/data/palette.json","node_modules/react-dom/client.js","node_modules/react-dom/cjs/react-dom-client.development.js","node_modules/scheduler/index.js","node_modules/scheduler/cjs/scheduler.development.js","node_modules/react-dom/index.js","node_modules/react-dom/cjs/react-dom.development.js","src/level_editor/levels_editor_util.ts","node_modules/@parcel/transformer-js/src/esmodule-helpers.js","src/pure_functions.ts","src/level_code_to_raw_level.ts","src/toast.ts","src/loadGameData.ts","src/data/levels.json","src/data/version.json","src/upgrades.ts","src/i18n/i18n.ts","src/i18n/en.json","src/i18n/cs.json","src/i18n/pl.json","src/i18n/zh.json","src/i18n/fr.json","src/i18n/pt_BR.json","src/i18n/pt.json","src/i18n/zh_Hant.json","src/i18n/es.json","src/i18n/de.json","src/i18n/it.json","src/i18n/fa.json","src/i18n/ru.json","src/i18n/ar.json","src/i18n/tr.json","src/i18n/ja.json","src/i18n/ko.json","src/i18n/sk.json","src/i18n/ro.json","src/i18n/uk.json","src/settings.ts","src/getLevelBackground.ts","src/data/backgrounds.json","src/data/unlockConditions.json","src/categoryNames.ts"],"sourcesContent":["import { Palette, RawLevel } from \"../types\";\nimport _palette from \"../data/palette.json\";\nimport { createRoot } from \"react-dom/client\";\nimport { useEffect, useState } from \"react\";\nimport { moveLevel, resizeLevel, setBrick } from \"./levels_editor_util\";\nimport { automaticBackgroundColor } from \"../pure_functions\";\nimport { levelCodeToRawLevel } from \"../level_code_to_raw_level\";\n\nconst palette = _palette as Palette;\n\nlet allLevels = null;\n\nfunction App() {\n  const [editingIndex, setEditingIndex] = useState(0);\n  const [selected, setSelected] = useState(\"W\");\n  const [applying, setApplying] = useState(\"\");\n  const [levels, setLevels] = useState<RawLevel[]>([]);\n  useEffect(() => {\n    fetch(\"http://localhost:4400/src/data/levels.json\")\n      .then((r) => r.json())\n      .then((lvls) => {\n        const cleaned = lvls.map((l) => ({\n          name: l.name.trim(),\n          size: l.size,\n          bricks: (l.bricks + \"_\".repeat(l.size * l.size)).slice(\n            0,\n            l.size * l.size,\n          ),\n          credit: l.credit?.trim() || \"\",\n          category: l.category?.trim() || \"\",\n          author: l.author?.trim() || \"\",\n        }));\n        const sorted = [\n          ...cleaned\n            .filter((l) => l.name.match(\"icon:\"))\n            .sort((a, b) => (a.name > b.name ? 1 : -1)),\n          ...cleaned.filter((l) => !l.name.match(\"icon:\")),\n        ];\n        setLevels(sorted as RawLevel[]);\n        allLevels = sorted;\n      });\n  }, []);\n\n  const updateLevel = (index: number, change: Partial<RawLevel>) => {\n    setLevels((list: RawLevel[]) =>\n      list.map((l, li) => (li === index ? { ...l, ...change } : l)),\n    );\n  };\n\n  const deleteLevel = (index: number) => {\n    if (confirm(\"Delete level\")) {\n      setLevels(levels.filter((l, i) => i !== index));\n    }\n  };\n  useEffect(() => {\n    if (!allLevels || JSON.stringify(allLevels) === JSON.stringify(levels))\n      return;\n    const timoutId = setTimeout(() => {\n      return fetch(\"http://localhost:4400/src/data/levels.json\", {\n        method: \"POST\",\n        headers: {\n          \"Content-Type\": \"text/plain\",\n        },\n        body: JSON.stringify(levels, null, 2),\n      });\n    }, 500);\n    return () => clearTimeout(timoutId);\n  }, [levels]);\n\n  const level = levels[editingIndex];\n\n  const content = (() => {\n    if (!level) return null;\n    const { name, credit, bricks, size, category, author } = level;\n\n    const brickButtons = [];\n    for (let x = 0; x < size; x++) {\n      for (let y = 0; y < size; y++) {\n        const index = y * size + x;\n        brickButtons.push(\n          <button\n            key={index}\n            onMouseDown={() => {\n              if (!applying) {\n                const color = selected === bricks[index] ? \"_\" : selected;\n                setApplying(color);\n                updateLevel(editingIndex, setBrick(level, index, color));\n              }\n            }}\n            onMouseEnter={() => {\n              if (applying) {\n                updateLevel(editingIndex, setBrick(level, index, applying));\n              }\n            }}\n            style={{\n              background: palette[bricks[index]] || \"transparent\",\n              left: x * 40,\n              top: y * 40,\n              width: 40,\n              height: 40,\n              position: \"absolute\",\n            }}\n          >\n            {(palette[bricks[index]] == \"black\" && \"💣\") || \" \"}\n          </button>,\n        );\n      }\n    }\n\n    return (\n      <>\n        <input\n          id={\"name\"}\n          type=\"text\"\n          value={name}\n          onChange={(e) => updateLevel(editingIndex, { name: e.target.value })}\n        />\n        <div id=\"credit\">\n          <input\n            placeholder=\"credit\"\n            type=\"text\"\n            value={credit || \"\"}\n            onChange={(e) =>\n              updateLevel(editingIndex, { credit: e.target.value })\n            }\n          />\n\n          <input\n            list=\"existing-categories\"\n            placeholder=\"category\"\n            type=\"text\"\n            value={category || \"\"}\n            onChange={(e) =>\n              updateLevel(editingIndex, { category: e.target.value })\n            }\n          />\n\n          <input\n            placeholder=\"author\"\n            list=\"existing-authors\"\n            type=\"text\"\n            value={author || \"\"}\n            onChange={(e) =>\n              updateLevel(editingIndex, { author: e.target.value })\n            }\n          />\n        </div>\n\n        <div id={\"tools\"}>\n          <button onClick={() => deleteLevel(editingIndex)}>Delete</button>\n          <button\n            onClick={() => updateLevel(editingIndex, resizeLevel(level, -1))}\n          >\n            -\n          </button>\n          <button\n            onClick={() => updateLevel(editingIndex, resizeLevel(level, +1))}\n          >\n            +\n          </button>\n          <button\n            onClick={() => updateLevel(editingIndex, moveLevel(level, -1, 0))}\n          >\n            L\n          </button>\n          <button\n            onClick={() => updateLevel(editingIndex, moveLevel(level, 1, 0))}\n          >\n            R\n          </button>\n          <button\n            onClick={() => updateLevel(editingIndex, moveLevel(level, 0, -1))}\n          >\n            U\n          </button>\n          <button\n            onClick={() => updateLevel(editingIndex, moveLevel(level, 0, 1))}\n          >\n            D\n          </button>\n        </div>\n\n        <div id=\"bricks\">\n          <div\n            id=\"level-bricks-preview\"\n            style={{\n              width: size * 40,\n              height: size * 40,\n              background: automaticBackgroundColor(bricks.split(\"\")),\n            }}\n          >\n            {brickButtons}\n          </div>\n        </div>\n      </>\n    );\n  })();\n\n  return (\n    <div\n      id={\"editor\"}\n      onMouseUp={() => {\n        setApplying(\"\");\n      }}\n    >\n      <div id=\"list\">\n        {levels.map((level, li) => (\n          <button\n            key={li}\n            className={li === editingIndex ? \"active\" : \"\"}\n            onClick={() => setEditingIndex(li)}\n          >\n            {level.name} {level.author ? \"✍️\" : \"\"} {level.category ? \"🗄️\" : \"\"}\n          </button>\n        ))}\n      </div>\n      <>{content}</>\n      <div id={\"palette\"}>\n        {Object.en