ires: [],\n    threshold: 380000,\n    id: \"soft_touch\",\n    max: 1,\n    hardLimit: 2,\n    name: t(\"upgrades.soft_touch.name\"),\n    help: (lvl: number) => t(\"upgrades.soft_touch.tooltip\"),\n    fullHelp: (lvl: number) => t(\"upgrades.soft_touch.verbose_description\"),\n  },\n\n  {\n    category: categories.advanced,\n    requires: [],\n    threshold: 400000,\n    id: \"instant_explosion\",\n    max: 1,\n    hardLimit: 1,\n    name: t(\"upgrades.instant_explosion.name\"),\n    help: (lvl: number) => t(\"upgrades.instant_explosion.tooltip\"),\n    fullHelp: (lvl: number) =>\n      t(\"upgrades.instant_explosion.verbose_description\"),\n  },\n  {\n    category: categories.advanced,\n    requires: [],\n    threshold: 410000,\n    id: \"soft_brush\",\n    max: 7,\n    hardLimit: Infinity,\n    name: t(\"upgrades.soft_brush.name\"),\n    help: (lvl: number) => t(\"upgrades.soft_brush.tooltip\"),\n    fullHelp: (lvl: number) => t(\"upgrades.soft_brush.verbose_description\"),\n  },\n  {\n    category: categories.advanced,\n    requires: [],\n    threshold: 420000,\n    id: \"fumes\",\n    max: 1,\n    hardLimit: 2,\n    name: t(\"upgrades.fumes.name\"),\n    help: (lvl: number) => t(\"upgrades.fumes.tooltip\"),\n    fullHelp: (lvl: number) => t(\"upgrades.fumes.verbose_description\"),\n  },\n\n  {\n    category: categories.advanced,\n    requires: [],\n    threshold: 430000,\n    id: \"hardhat\",\n    max: 1,\n    hardLimit: 3,\n    name: t(\"upgrades.hardhat.name\"),\n    help: (lvl: number) => t(\"upgrades.hardhat.tooltip\"),\n    fullHelp: (lvl: number) => t(\"upgrades.hardhat.verbose_description\"),\n  },\n] as const;\n","import en from \"./en.json\";\nimport cs from \"./cs.json\";\nimport pl from \"./pl.json\";\nimport zh from \"./zh.json\";\nimport fr from \"./fr.json\";\nimport br from \"./pt_BR.json\";\nimport pt from \"./pt.json\";\nimport zh_Hant from \"./zh_Hant.json\";\nimport es from \"./es.json\";\nimport de from \"./de.json\";\nimport it from \"./it.json\";\nimport fa from \"./fa.json\";\nimport ru from \"./ru.json\";\nimport ar from \"./ar.json\";\nimport tr from \"./tr.json\";\nimport ja from \"./ja.json\";\nimport ko from \"./ko.json\";\nimport sk from \"./sk.json\";\nimport ro from \"./ro.json\";\nimport uk from \"./uk.json\";\n\nimport { getSettingValue } from \"../settings\";\n\nexport const languages = [\n  {\n    text: \"English\",\n    value: \"en\",\n    strings: en,\n    levelName: \"UK\",\n  },\n  {\n    text: \"Français\",\n    value: \"fr\",\n    strings: fr,\n    levelName: \"France\",\n  },\n  {\n    text: \"汉语\",\n    value: \"zh\",\n    strings: zh,\n    levelName: \"China\",\n    limitTextWeight: true,\n  },\n  {\n    text: \"正體字\",\n    value: \"zh_Hant\",\n    strings: zh_Hant,\n    levelName: \"Taiwan\",\n    limitTextWeight: true,\n  },\n  {\n    text: \"Brasil\",\n    value: \"br\",\n    strings: br,\n    levelName: \"Brazil\",\n  },\n  {\n    text: \"Português\",\n    value: \"pt\",\n    strings: pt,\n    levelName: \"Portugal\",\n  },\n  {\n    text: \"عربي\",\n    value: \"ar\",\n    strings: ar,\n    levelName: \"Lebanon\",\n  },\n  {\n    text: \"Español\",\n    value: \"es\",\n    strings: es,\n\n    levelName: \"Chile\",\n  },\n  {\n    text: \"Русский\",\n    value: \"ru\",\n    strings: ru,\n    levelName: \"Russia\",\n  },\n\n  {\n    text: \"Deutsch\",\n    value: \"de\",\n    strings: de,\n    levelName: \"Germany\",\n  },\n  {\n    text: \"Türkçe\",\n    value: \"tr\",\n    strings: tr,\n\n    levelName: \"Türkiye\",\n  },\n  {\n    text: \"한국인\",\n    value: \"ko\",\n    strings: ko,\n    levelName: \"Korea\",\n    limitTextWeight: true,\n  },\n  {\n    text: \"فارسی\",\n    value: \"fa\",\n    strings: fa,\n    levelName: \"Iran\",\n  },\n  {\n    text: \"日本語\",\n    value: \"ja\",\n    strings: ja,\n    levelName: \"Japan\",\n  },\n  {\n    text: \"Slovenčina\",\n    value: \"sk\",\n    strings: sk,\n    levelName: \"Slovakia\",\n  },\n  {\n    text: \"Italiano\",\n    value: \"it\",\n    strings: it,\n    levelName: \"Italia\",\n  },\n  {\n    text: \"čeština\",\n    value: \"cs\",\n    strings: cs,\n    levelName: \"Czech Republic\",\n  },\n  {\n    text: \"Polski\",\n    value: \"pl\",\n    strings: pl,\n    levelName: \"Poland\",\n  },\n  {\n    text: \"Română\",\n    value: \"ro\",\n    strings: ro,\n    levelName: \"Romania\",\n  },\n  {\n    text: \"українська\",\n    value: \"uk\",\n    strings: uk,\n    levelName: \"Ukraine\",\n  },\n];\n\ntype translationKeys = keyof typeof en;\ntype translation = {\n  strings: { [key in translationKeys]: string };\n  limitTextWeight?: boolean;\n};\nconst languagesMap: Record<string, translation> = {};\nlanguages.forEach((l) => (languagesMap[l.value] = l));\n\nlet defaultLang =\n  [...navigator.languages, navigator.language]\n    .filter((i) => i)\n    .map((i) => i.slice(0, 2).toLowerCase())\n    .find((k) => k in languagesMap) || \"en\";\n\nexport function getCurrentLang() {\n  return getSettingValue(\"lang\", defaultLang);\n}\n\nexport function t(\n  key: translationKeys,\n  params: { [key: string]: any } = {},\n): string {\n  const lang = getCurrentLang();\n  let template =\n    languagesMap[lang]?.strings[key] || languagesMap.en.strings[key];\n  if (typeof template == \"undefined\")\n    throw new Error(\"Missing translation key :\" + key);\n  for (let key in params) {\n    template = template.split(\"{{\" + key + \"}}\").join(`${params[key]}`);\n  }\n  return template.replace(/</gi, \"&lt;\").replace(/>/gi, \"&gt;\");\n}\n\nconst supportsBold: Record<string, (typeof languages)[0]> = {};\nlanguages.forEach((l) => {\n  supportsBold[l.value] = l;\n});\nexport function currentLanguageSupportsHeavyFontWeight() {\n  return !languagesMap[getCurrentLang()].limitTextWeight;\n}\n","{\n    \"confirmRestart.no\": \"Cancel\",\n    \"confirmRestart.text\": \"You're about to start a new game. Are you sure you want to continue?\",\n    \"confirmRestart.title\": \"Start a new game?\",\n    \"confirmRestart.yes\": \"Restart game\",\n    \"editor.editing.author\": \"Author\",\n    \"editor.editing.author_prompt\": \"Enter your own name. Don't put links here. This field should be the same for all the levels you submit.\",\n    \"editor.editing.author_required\": \"Please enter your name in \\\"Author\\\" first\",\n    \"editor.editing.bigger\": \"Increase level size\",\n    \"editor.editing.category\": \"Category\",\n    \"editor.editing.category_prompt\": \"Select the category best matching your level\",\n    \"editor.editing.color\": \"Pick a color in the color list (max 5 per level)\",\n    \"editor.editing.copied\": \"Level code copied\",\n    \"editor.editing.copy\": \"Copy level code\",\n    \"editor.editing.copy_help\": \"Share the level code in our discord for inclusion in the game.\",\n    \"editor.editing.credit\": \"Credits and source\",\n    \"editor.editing.credit_prompt\": \"Enter the source url or explanation of your level.\",\n    \"editor.editing.delete\": \"Delete level\",\n    \"editor.editing.delete_confirm\": \"Are you sure you want to delete this level ?\",\n    \"editor.editing.delete_no\": \"Cancel\",\n    \"editor.editing.delete_yes\": \"Yes, delete it\",\n    \"editor.editing.down\": \"Move down all the bricks\",\n    \"editor.editing.help\": \"Then click a tile to color it.\",\n    \"editor.editing.left\": \"Move all bricks to the left\",\n    \"editor.editing.play\": \"Play this level\",\n    \"editor.editing.rename\": \"Rename level\",\n    \"editor.editing.rename_prompt\": \"Please enter a new name for the level.\",\n    \"editor.editing.right\": \"Move all bricks to the right\",\n    \"editor.editing.show_code\": \"Show level code\",\n    \"editor.editing.show_code_help\": \"You can then copy it manually.\",\n    \"editor.editing.smaller\": \"Decrease level size\",\n    \"editor.editing.title\": \"Editing level : {{name}}\",\n    \"editor.editing.up\": \"Move up all the bricks\",\n    \"editor.help\": \"Create custom levels and share them for inclusion in the game.\",\n    \"editor.import\": \"Import a level\",\n    \"editor.import_instruction\": \"Paste a level code to import it in your level list\",\n    \"editor.leave_preview\": \"Back to editor\",\n    \"editor.new_level\": \"New level\",\n    \"editor.title\": \"Level Editor\",\n    \"gameOver.creative\": \"This run will not be recorded.\",\n    \"gameOver.cumulative_total\": \"Your total cumulative score went from {{startTs}} to {{endTs}}.\",\n    \"gameOver.double_or_nothing.summary\": \"The combo was reset, which ended the whole run because of the \\\"{{perk}}\\\" upgrade.\",\n    \"gameOver.double_or_nothing.title\": \"Game over\",\n    \"gameOver.lastLevelSummary\": \"In level {{level}} you caught {{levelCaughtCoins}} coins out of {{levelSpawnedCoins}} ({{catchRate}}%) in {{duration}} seconds. The ball missed the bricks {{levelMisses}} time(s)\",\n    \"gameOver.lost.summary\": \"You dropped the ball, ending your run.\",\n    \"gameOver.lost.title\": \"Game Over\",\n    \"gameOver.stats.balls_lost\": \"Balls lost\",\n    \"gameOver.stats.bricks_broken\": \"Bricks broken\",\n    \"gameOver.stats.bricks_per_minute\": \"Bricks broken per minute\",\n    \"gameOver.stats.catch_rate\": \"Catch rate\",\n    \"gameOver.stats.combo_avg\": \"Average combo\",\n    \"gameOver.stats.combo_max\": \"Max combo\",\n    \"gameOver.stats.duration_per_level\": \"Duration per level\",\n    \"gameOver.stats.hit_rate\": \"Hit rate\",\n    \"gameOver.stats.level_reached\": \"Level reached\",\n    \"gameOver.stats.total_score\": \"Total score\",\n    \"gameOver.stats.upgrades_applied\": \"Upgrades applied\",\n    \"gameOver.stats_intro\": \"Find below your game statistics compared to  your {{count}} best games.\",\n    \"gameOver.total\": \"During this run, you caught a total of {{score}} coins.\",\n    \"gameOver.unlocked_perk\": \"Upgrade unlocked\",\n    \"gameOver.unlocked_perk_plural\": \"You just unlocked {{count}} perks\",\n    \"gameOver.win.summary\": \"This game is over.\",\n    \"gameOver.win.title\": \"You completed this game\",\n    \"help.content\": \"## Goal\\n\\nCatch as many coins as possible during 7 levels.\\nCoins appear when you break bricks.\\nCatch them with your paddle to increase your score.\\nYour score is displayed in the top right corner of the screen.\\nDon't drop the ball or it's game over.\\n\\nAfter destroying all bricks, you'll get to pick an upgrade.\\n\\n## Upgrades\\n\\nThe upgrades you pick will apply until the end of the run.\\nSome can be picked multiple times for stronger effect.\\nSome help with aiming, or make the game easier in some other ways.\\nSome are only useful when combined.\\n\\nYou always get one upgrade at the beginning of each game.\\nIts icon will serve as the bricks of the first level.\\nYou can select the starting upgrade you prefer in the main menu.\\n\\nMany upgrades impact your combo.\\n\\n## Combo\\n\\nYour \\\"combo\\\" is the number of coins spawned when a brick breaks.\\nIt is displayed on your paddle, for example 🪙4 means each brick will spawn 4 coins.\\nMost upgrades that increase the combo also add a condition to reduce it.\\nThe combo will reset to the minimum if the ball returns to the paddle without hitting any brick. A \\\"miss\\\" message will be shown when that happens.\\n\\nTry to aim towards a brick every time.\\n\\n## Aiming\\n\\nOnly the ball position on the paddle decides how it will bounce.\\nIf the ball hits the paddle dead center, it will bounce back up vertically.\\nIf you hit more on one side, it will have more angle.\\nThe paddle speed and incoming angle have no impact on the ball direction after bouncing.\\n\\nMany upgrades that help with aiming can be unlocked.\\n\\n## Unlocks\\n\\nWhen playing Breakout 71 for the first time, most upgrades and levels are locked.\\nUpgrades are unlocked by simply playing and catching many coins.\\nThe first levels are unlocked by reaching a high score.\\nLater levels add a condition about which perks you can select.\\n\\nReach high scores is much easier when you get multiple upgrades per level thanks to medals.\\n\\n## Medals\\n\\nYou'll get an extra upgrades and choices when you play well :\\n\\n- Clear the level quickly\\n- Catch all the coins\\n- Always hit something between paddle bounces\",\n    \"help.help\": \"Learn more about the game\",\n    \"help.title\": \"Help\",\n    \"history.columns.mainPerkId\": \"Starting perk\",\n    \"history.columns.score\": \"Score\",\n    \"history.columns.started\": \"Date\",\n    \"history.help\": \"See your {{count}} best games.\",\n    \"history.include_past_versions\": \"Show past versions too\",\n    \"history.locked\": \"Play at least ten games to unlock\",\n    \"history.title\": \"Runs history\",\n    \"lab.help\": \"Try any build you want.\",\n    \"lab.instructions\": \"Select upgrades and a level, then click the play button above.\",\n    \"lab.menu_entry\": \"Creative mode\",\n    \"lab.play\": \"Play\",\n    \"lab.reset\": \"Reset\",\n    \"lab.select_level\": \"Select a level to play on\",\n    \"lab.unlocks_at\": \"Unlocks at total score {{score}}\",\n    \"level_up.challenges.catchRateGood.description\": \"Catch {{gold}}% of coins for gold,  {{silver}}% for silver.\",\n    \"level_up.challenges.catchRateGood.name\": \"{{caught}} coins caught out of {{total}}\",\n    \"level_up.challenges.earned_medal\": \"You earned a medal\",\n    \"level_up.challenges.earned_medal_plural\": \"You earned {{count}} medals\",\n    \"level_up.challenges.gain\": \"+{{choices}} choices and +{{up}} upgrades\",\n    \"level_up.challenges.levelMisses.description\": \"You'll get a gold medal if you miss less than {{gold}} times, silver under {{silver}}.\",\n    \"level_up.challenges.levelMisses.name\": \"{{value}} missed shots\",\n    \"level_up.challenges.levelMisses.none\": \"No missed shots\",\n    \"level_up.challenges.levelTime.description\": \"You'll get a gold medal under {{gold}}s and a silver medal under {{silver}}s.\",\n 