   \"settings.load_save_file_help\": \"Vyberte súbor na vašom zariadení\",\n    \"settings.max_coins\": \"{{max}} mince na obrazovke maximálne\",\n    \"settings.max_coins_help\": \"Cosmetic iba, žiadny účinok na skóre\",\n    \"settings.menu_sound\": \"\",\n    \"settings.menu_sound_help\": \"\",\n    \"settings.missed_shot_trail\": \"\",\n    \"settings.missed_shot_trail_help\": \"\",\n    \"settings.mobile\": \"Mobilný režim\",\n    \"settings.mobile_help\": \"Zanecháva priestor pod paddleboardom.\",\n    \"settings.notch_space\": \"\",\n    \"settings.notch_space_help\": \"\",\n    \"settings.particles\": \"\",\n    \"settings.particles_help\": \"\",\n    \"settings.pointer_lock\": \"Zámok myši\",\n    \"settings.pointer_lock_help\": \"Zámky a skrýva kurzor myši.\",\n    \"settings.precise_lighting\": \"Presné osvetlenie\",\n    \"settings.precise_lighting_help\": \"Použite menšie mriežky pre efekt osvetlenia pozadia\",\n    \"settings.probabilistic_lighting\": \"Prítomnosť vízie\",\n    \"settings.probabilistic_lighting_help\": \"Zlepšiť výkon, keď existuje viac ako 150 mincí tým, že reusing niektoré z svetla predchádzajúceho rámu\",\n    \"settings.record\": \"Nahrať hry videá\",\n    \"settings.record_download\": \"Stiahnuť video ({{size}} MB)\",\n    \"settings.record_help\": \"Získajte video z každej úrovne.\",\n    \"settings.reset\": \"Obnoviť hru\",\n    \"settings.reset_cancel\": \"Nie\",\n    \"settings.reset_confirm\": \"Áno\",\n    \"settings.reset_help\": \"Erase vysoké skóre, hrať čas a štatistiky\",\n    \"settings.reset_instruction\": \"Budete stratiť všetky pokrok ste urobili v hre, ste si istí?\",\n    \"settings.save_file_error\": \"Chyba nakladanie uložiť súbor\",\n    \"settings.save_file_loaded\": \"Uložiť súbor naložený\",\n    \"settings.save_file_loaded_help\": \"Aplikácia bude teraz preťažiť, aby sa vaše uloženie\",\n    \"settings.save_file_loaded_ok\": \"Okno\",\n    \"settings.short_numbers\": \"\",\n    \"settings.short_numbers_help\": \"\",\n    \"settings.show_fps\": \"FPS pult\",\n    \"settings.show_fps_help\": \"Monitorovať výkon aplikácie\",\n    \"settings.show_puck_rails\": \"\",\n    \"settings.show_puck_rails_help\": \"\",\n    \"settings.show_stats\": \"Zobraziť skutočné časové štatistiky\",\n    \"settings.show_stats_help\": \"Mince, čas, Chýba\",\n    \"settings.smooth_lighting\": \"Hladké osvetlenie\",\n    \"settings.smooth_lighting_help\": \"Rozmazať efekty osvetlenia pozadia, aby vyzerali menej štvorca. Zvyšuje lag.\",\n    \"settings.sounds\": \"Zvuky hry\",\n    \"settings.sounds_help\": \"Včely, bloops a brrrr\",\n    \"settings.stress_test\": \"Test stresu\",\n    \"settings.stress_test_help\": \"Začnite bot kontrolovanú hru s veľmi vysokým počtom mincí, aby ste testovali limity výkonu vášho zariadenia.\",\n    \"settings.suggestions.applied\": \"Návrh výkonu aplikovaný!\",\n    \"settings.suggestions.basic_mode\": \"Návrhy: obrátiť základný režim na zlepšenie výkonu.\",\n    \"settings.suggestions.record\": \"Návrhy: Disable video nahrávanie na zlepšenie výkonu.\",\n    \"settings.touch_delayed_start\": \"Odinštalovaný štart na mobilnom telefóne\",\n    \"settings.touch_delayed_start_help\": \"3,2,1, Choďte na začiatku úrovne\",\n    \"unlocks.category.advanced\": \"\",\n    \"unlocks.category.beginner\": \"\",\n    \"unlocks.category.combo\": \"\",\n    \"unlocks.category.combo_boost\": \"\",\n    \"unlocks.category.pierce\": \"\",\n    \"unlocks.category.simple\": \"\",\n    \"unlocks.extra_perks_for_preview\": \"\",\n    \"unlocks.greyed_out_help\": \"\",\n    \"unlocks.include_in_level_pool\": \"\",\n    \"unlocks.include_in_level_pool_help\": \"\",\n    \"unlocks.include_in_level_pool_locked\": \"\",\n    \"unlocks.include_in_unlock_hints_help\": \"\",\n    \"unlocks.include_in_unlock_not_during_gameplay\": \"\",\n    \"unlocks.intro\": \"\",\n    \"unlocks.just_unlocked\": \"\",\n    \"unlocks.just_unlocked_plural\": \"\",\n    \"unlocks.level\": \"\",\n    \"unlocks.level_description\": \"\",\n    \"unlocks.level_locked\": \"\",\n    \"unlocks.level_unlocked\": \"\",\n    \"unlocks.levels\": \"\",\n    \"unlocks.levels_categories.abstract\": \"\",\n    \"unlocks.levels_categories.animals\": \"\",\n    \"unlocks.levels_categories.flags\": \"\",\n    \"unlocks.levels_categories.games\": \"\",\n    \"unlocks.levels_categories.landscapes\": \"\",\n    \"unlocks.levels_categories.portraits\": \"\",\n    \"unlocks.levels_categories.stills\": \"\",\n    \"unlocks.levels_categories.symbols\": \"\",\n    \"unlocks.levels_categories_rules.abstract\": \"\",\n    \"unlocks.levels_categories_rules.animals\": \"\",\n    \"unlocks.levels_categories_rules.flags\": \"\",\n    \"unlocks.levels_categories_rules.games\": \"\",\n    \"unlocks.levels_categories_rules.landscapes\": \"\",\n    \"unlocks.levels_categories_rules.portraits\": \"\",\n    \"unlocks.levels_categories_rules.stills\": \"\",\n    \"unlocks.levels_categories_rules.symbols\": \"\",\n    \"unlocks.levels_help\": \"\",\n    \"unlocks.minScore\": \"\",\n    \"unlocks.minScoreWithPerks\": \"\",\n    \"unlocks.minScoreWithPerksNoForbidden\": \"\",\n    \"unlocks.minTotalScore\": \"\",\n    \"unlocks.next\": \"\",\n    \"unlocks.previous\": \"\",\n    \"unlocks.reached\": \"\",\n    \"unlocks.requires\": \"\",\n    \"unlocks.requires_one\": \"\",\n    \"unlocks.sort_author\": \"\",\n    \"unlocks.sort_bombs\": \"\",\n    \"unlocks.sort_bombs_label\": \"\",\n    \"unlocks.sort_bombs_label_0\": \"\",\n    \"unlocks.sort_bombs_label_1\": \"\",\n    \"unlocks.sort_bricks\": \"\",\n    \"unlocks.sort_bricks_label\": \"\",\n    \"unlocks.sort_category\": \"\",\n    \"unlocks.sort_colors\": \"\",\n    \"unlocks.sort_colors_label\": \"\",\n    \"unlocks.sort_colors_label_1\": \"\",\n    \"unlocks.sort_size\": \"\",\n    \"unlocks.sort_unlocked\": \"\",\n    \"unlocks.start_new_game_with\": \"\",\n    \"unlocks.start_new_game_with_help\": \"\",\n    \"unlocks.title_upgrades\": \"\",\n    \"unlocks.try\": \"Vyskúšať\",\n    \"unlocks.unlock_condition\": \"\",\n    \"unlocks.upgrade_choice_perk\": \"\",\n    \"unlocks.upgrade_choice_perk_help\": \"\",\n    \"unlocks.upgrade_incompatibilities\": \"\",\n    \"unlocks.upgrade_synergies\": \"\",\n    \"unlocks.upgrades\": \"Odomknuté upgrady\",\n    \"unlocks.upgrades_help\": \"\",\n    \"unlocks.use\": \"Použitie\",\n    \"upgrades.addiction.name\": \"Závislosť\",\n    \"upgrades.addiction.tooltip\": \"Viac mincí, ak zlomíte tehly bez pauzy\",\n    \"upgrades.addiction.verbose_description\": \"+{{lvl}} combo / tehla rozbité, combo resetuje {{delay}} po rozpade tehly. odpočítavanie len začína po rozpade prvej tehly každej úrovne. Zastavuje hneď, ako sú všetky tehly zničené.\",\n    \"upgrades.asceticism.name\": \"Asceticizmus\",\n    \"upgrades.asceticism.tooltip\": \"+{{combo}} combo na tehly rozbité, -{{loss}} combo na mince chytený.\",\n    \"upgrades.asceticism.verbose_description\": \"Budete musieť uložiť mince niekde, zatiaľ čo vaše horolezectvo.\",\n    \"upgrades.ball_attract_ball.name\": \"Gravity\",\n    \"upgrades.ball_attract_ball.tooltip\": \"Lopty priťahujú gule\",\n    \"upgrades.ball_attract_ball.verbose_description\": \"Lopty, ktoré sú viac ako \\\"3/4 šírky hernej plochy\\\" sa začínajú navzájom priťahovať.\\n\\nAtrakcia sila je silnejšia, keď sú od seba kožušiny.\\n\\nDúhové častice budú lietať symbolizovať lákavú silu. Tento perk sa ponúka len vtedy, ak máte viac ako jednu loptu už.\",\n    \"upgrades.ball_attracts_coins.name\": \"Lopty priťahujú mince\",\n    \"upgrades.ball_attracts_coins.tooltip\": \"Mince nasledovať najbližšie loptu\",\n    \"upgrades.ball_attracts_coins.verbose_description\": \"To by mohlo byť použité na \\\"paint okolo\\\" guľôčky s mince, ak ste spojili s \\\"stain\\\" a \\\"host mince\\\". Funguje tiež ako náhrada mince magnet.\",\n    \"upgrades.ball_repulse_ball.name\": \"Osobný priestor\",\n    \"upgrades.ball_repulse_ball.tooltip\": \"Lopty repulzné gule\",\n    \"upgrades.ball_repulse_ball.verbose_description\": \"Lopty, ktoré sú menej ako štvrtinu šírku obrazovky, sa začínajú navzájom odpudzovať. Repulzačná sila je silnejšia, ak sú navzájom blízko. Časti budú vyčerpať symbolizovať túto silu. Tento perk sa ponúka len vtedy, ak máte viac ako jednu loptu už.\",\n    \"upgrades.base_combo.name\": \"Silné základy\",\n    \"upgrades.base_combo.tooltip\": \"3 viac mincí za tehlu rozbité\",\n    \"upgrades.base_combo.verbose_description\": \"Váš hrebeň zvyčajne začína na 1 na začiatku úrovne, a resetuje na 1, keď odrazíte bez biť nič. S týmto perk, combo začína 3 body vyššie, takže budete vždy získať aspoň 4 mince na tehlu. Vždy, keď sa váš hrebeň reset, vráti sa späť na 4 a nie 1. Vaša lopta bude trblietať trochu naznačovať, že jeho česano je vyšší ako jeden. Na úrovni 2, dodáva 4 mince, potom 5, potom 6 ..\",\n    \"upgrades.bigger_balls.name\": \"\",\n    \"upgrades.bigger_balls.tooltip\": \"\",\n    \"upgrades.bigger_balls.verbose_description\": \"\",\n    \"upgrades.bigger_explosions.name\": \"Všeobecný\",\n    \"upgrades.bigger_explosions.tooltip\": \"Veľké výbuchy\",\n    \"upgrades.bigger_explosions.verbose_description\": \"Predvolené výbuch vyčnieva štvorcové námestie 3x3, s tým sa stáva 5x5 štvorec a rana na mince je tiež výrazne silnejší. Obraz bude blesk po každom výbuchu (okrem základného režimu)\",\n    \"upgrades.bigger_puck.name\": \"Veľký paddleboard\",\n    \"upgrades.bigger_puck.tooltip\": \"Ľahko chytiť viac mincí\",\n    \"upgrades.bigger_puck.verbose_description\": \"Väčší paddleboard uľahčuje nikdy ujsť loptu a chytiť viac mincí, a tiež presne uhol odrazy ( uhol lopty závisí len na tom, kde zasiahne pád).\",\n    \"upgrades.bricks_attract_ball.name\": \"Bricks priťahuje gule\",\n    \"upgrades.bricks_attract_ball.tooltip\": \"Lopta ide smerom k blízkosti tehál\",\n    \"upgrades.bricks_attract_ball.verbose_description\": \"Lopta ide smerom k prvému {{count}} tehly to bude hit. Účinok je silnejší na vyššej úrovni. Počet tehál, ktoré môžu zasiahnuť pred zastavením účinku je tiež vyššia. Účinok zamračené, keď lopta zasiahne paddleboard.\",\n    \"upgrades.bricks_attract_coins.name\": \"Bricks priťahuje mince\",\n    \"upgrades.bricks_attract_coins.tooltip\": \"Pomáha im zostať tam\",\n    \"upgrades.bricks_attract_coins.verbose_description\": \"Mince budú priťahované do blízkych tehál. Na vyšších úrovniach je príťažlivosť silnejší.\",\n    \"upgrades.buoy.name\": \"Buoy\",\n    \"upgrades.buoy.tooltip\": \"Mince plávajú na {{duration}} sekúnd na spodnom riadku.\",\n    \"upgrades.buoy.verbose_description\": \"Účinok je najviac viditeľný v mobilnom režime\",\n    \"upgrades.chill.name\": \"Chill\",\n    \"upgrades.chill.tooltip\": \"Žiadne ďalšie upgrady, neobmedzené úrovne.\",\n    \"upgrades.chill.verbose_description\": \"Loptu tiež urýchľuje oveľa pomalšie.\",\n    \"upgrades.clairvoyant.name\": \"Všeobecný\",\n    \"upgrades.clairvoyant.tooltip\": \"Pozrite sa na nadchádzajúce úrovne, tehly HP a loptu smer\",\n    \"upgrades.clairvoyant.verbose_description\": \"Pomáha vám vybrať správne upgrady a pochopiť, čo sa deje s robustnými tehlami. Level 2 a 3 prinášajú ďalšie znalosti pochybného nástroja (rozšíriteľné v režime slučky)\",\n    \"upgrades.coin_magnet.name\": \"Mince magnet\",\n    \"upgrades.coin_magnet.tooltip\": \"Paddleboard priťahuje mince\",\n    \"upgrades.coin_magnet.verbose_description\": \"Priťahuje mince na paddleboard. Účinok je silnejší, ak je mince blízko nej už.\",\n    \"upgrades.compound_interest.name\": \"Zlúčeniny záujem\",\n    \"upgrades.compound_interest.tooltip\": \"Viac mincí, ak chytíte všetky mince\",\n    \"upgrades.compound_interest.verbose_description\": \"Váš hrebeň bude rásť raz zakaždým, keď rozbijete tehál, prerezávate viac a viac mincí s každou tehálou.\\nUistite sa však chytiť každý z týchto mincí s lopatou, pretože akákoľvek stratená mince obnoví vaše česanie.\\nAkonáhle je váš hrebeň nad minimálnou, dno hracej plochy bude mať červenú líniu, aby vám pripomenul, že mince by nemali ísť tam.\",\n    \"upgrades.concave_puck.name\": \"S pozdravom paddleboard\",\n    \"upgrades.concave_puck.tooltip\": \"Zlepšuje vertikálnu presnosť zacielenia\",\n    \"upgrades.concave_puck.verbose_description\": \"Lopty začínajú úroveň ísť rovno hore, a odrazí s menším uhlom.\",\n    \"upgrades.corner_shot.name\": \"Rohový záber\",\n    \"upgrades.corner_shot.tooltip\": \"Nechajte si paddleboard prekrývať sa s hranicami obrazovky\",\n    \"upgrades.corner_shot.verbose_description\": \"Pomáha s cieľom v rohoch. Ďalšie úrovne nechať ísť ďalej.\",\n    \"upgrades.disco_ball.name\": \"\",\n    \"upgrades.disco_ball.tooltip\": \"\",\n    \"upgrades.disco_ball.verbose_description\": \"\",\n    \"upgrades.double_or_nothing.name\": \"Dvojité alebo nič\",\n    \"upgrades.double_or_nothing.tooltip\": \"\",\n    \"upgrades.double_or_nothing.verbose_description\": \"Horský reset počíta len vtedy, keď váš hrebeň bol nad minimálnou\",\n    \"upgrades.etherealcoins.name\": \"Mince, v priestore\",\n    \"upgrades.etherealcoins.tooltip\": \"Mince už nie sú ovplyvnené gravitáciou\",\n    \"upgrades.etherealcoins.verbose_description\": \"Mince budú udržiavať svoju rýchlosť aj po niekoľkých odrazí, a už nebudú ovplyvnené gravitáciou.\",\n    \"upgrades.extra_levels.name\": \"5 min viac\",\n    \"upgrades.extra_levels.tooltip\": \"Hrať {{count}} úrovne namiesto 7\",\n    \"upgrades.extra_levels.verbose_description\": \"Predvolená hra môže trvať maximálne 7 úrovní, po ktorej je hra skončila.\\n\\nKaždá úroveň tohto perka umožňuje ísť o jednu úroveň vyššie. Posledné úrovne sú často tie, kde urobíte najviac skóre, takže rozdiel môže byť dramatický.\",\n    \"upgrades.extra_life.name\": \"Extra život\",\n    \"upgrades.extra_life.tooltip\": \"Uloží vašu poslednú loptu, ak sa chystá byť stratený\",\n    \"upgrades.extra_life.verbose_description\": \"Život bude konzumovaný v procese. Extra životy ukazujú, ako pri líniách za pádom.\",\n    \"upgrades.flyswatter.name\": \"\",\n    \"upgrades.flyswatter.tooltip\": \"\",\n    \"upgrades.flyswatter.verbose_description\": \"\",\n    \"upgrades.forgiving.name\": \"Prevzdania\",\n    \"upgrades.forgiving.tooltip\": \"Prvýkrát, keď loptička minie všetky tehly v úrovni, sa ignoruje.\",\n    \"upgrades.forgiving.verbose_description\": \"\",\n    \"upgrades.fountain_toss.name\": \"Fontány\",\n    \"upgrades.fountain_toss.tooltip\": \"Gain combo, keď vynecháte mince.\",\n    \"upgrades.fountain_toss.verbose_description\": \"Keď vynecháte mincu a váš hrebeň bol pod úrovňou * 30, váš hrebeň má pravdepodobnosť úrovne/kombo rásť jeden.\",\n    \"upgrades.fumes.name\": \"\",\n    \"upgrades.fumes.tooltip\": \"\",\n    \"upgrades.fumes.verbose_description\": \"\",\n    \"upgrades.ghost_coins.name\": \"Ghost mince\",\n    \"upgrades.ghost_coins.tooltip\": \"Mince pomaly prejsť cez tehly\",\n    \"upgrades.ghost_coins.verbose_description\": \"Nie je to chyba, je to funkcia! Mince letia cez tehly pomaly. Vyššie úrovne nechať ich pohybovať rýchlejšie.\",\n    \"upgrades.golden_goose.name\": \"Zlatý hus\",\n    \"upgrades.golden_goose.tooltip\": \"Mince teleport na loptu po zasiahnutí tehly\",\n    \"upgrades.golden_goose.verbose_description\": \"Kedykoľvek mince hity tehla, teleport, že mince do najbližšieho lopty. Na úrovni dva, mince teleport po biť stranu tiež.\",\n    \"upgrades.gravity_falls.name\": \"\",\n    \"upgrades.gravity_falls.tooltip\": \"\",\n    \"upgrades.gravity_falls.verbose_description\": \"\",\n    \"upgrades.happy_family.name\": \"Šťastná rodina\",\n    \"upgrades.happy_family.tooltip\": \"Viac mincí, ak budete mať všetky guľôčky v hre.\",\n    \"upgrades.happy_family.verbose_description\": \"+1 combo za extra loptu na pád. Combo resetuje, keď je lopta stratená. Iba loptu nad 1 dať combo.\",\n    \"upgrades.hardhat.name\": \"\",\n    \"upgrades.hardhat.tooltip\": \"\",\n    \"upgrades.hardhat.verbose_description\": \"\",\n    \"upgrades.helium.name\": \"Hélium\",\n    \"upgrades.helium.tooltip\": \"Gravity obmedzená vľavo a doprava paddle\",\n    \"upgrades.helium.verbose_description\": \"Na úrovni 1 sa znižuje gravitácia. Na úrovni 2, mince pomaly plávajú. Na úrovni 3 naozaj lietať.\",\n    \"upgrades.hot_start.name\": \"Horúci začiatok\",\n    \"upgrades.hot_start.tooltip\": \"Viac mincí, ak vyčistite úroveň pod 30s\",\n    \"upgrades.hot_start.verbose_description\": \"Na začiatku každej úrovne začne váš hrebeň na +{{start}} bodov, ale potom každý druhý bude znížený {{loss}}. Účinok zásobníky s inými perks.\",\n    \"upgrades.implosions.name\": \"Zložky\",\n    \"upgrades.implosions.tooltip\": \"Explosions sať mince namiesto fúkania\",\n    \"upgrades.implosions.verbose_description\": \"Expresná sila sa aplikuje iným spôsobom. Ďalšie úrovne pôsobia ako \\\"bigger výbuch\\\"\",\n    \"upgrades.instant_explosion.name\": \"\",\n    \"upgrades.instant_explosion.tooltip\": \"\",\n    \"upgrades.instant_explosion.verbose_description\": \"\",\n    \"upgrades.left_is_lava.name\": \"Vyhnite sa ľavej strane\",\n    \"upgrades.left_is_lava.tooltip\": \"Viac mincí, ak sa nedotýkate ľavej strane\",\n    \"upgrades.left_is_lava.verbose_description\": \"Kedykoľvek rozbijete tehál, váš hrebeň sa zvýši jeden, takže dostanete jednu viac mincí zo všetkých ďalších tehálov, ktoré zlomíte.\\n\\nAvšak, váš hrebeň bude resetovať hneď, ako vaša lopta hity na ľavej strane .\\n\\nAkonáhle váš hrebeň stúpa, ľavá strana sa stáva červená, aby vám pripomenul, že by ste sa mali vyhnúť biť.\\n\\nNa úrovni 2 je hranica úplne odstránená a vaše guľôčky a mince by mohli stratiť.\",\n    \"upgrades.limitless.name\": \"Bez obmedzenia\",\n    \"upgrades.limitless.tooltip\": \"Zdvihnite maximálnu úroveň upgradu {{lvl}}\",\n    \"upgrades.limitless.verbose_description\": \"Výber tohto perku tiež zvyšuje svoj vlastný limit jedným, nechať si ho znova vybrať.\",\n    \"upgrades.metamorphosis.name\": \"Metamorfóza\",\n    \"upgrades.metamorphosis.tooltip\": \"Každá mince môže škvrnať {{lvl}} tehla (s) s jeho farbou\",\n    \"upgrades.metamorphosis.verbose_description\": \"S týmto perk, mince budú farba tehly pochádzajú, a bude farebná prvá tehla sa dotýkajú v rovnakej farbe. Mince šité s rýchlosťou lopty, ktorá ich rozbila, čo znamená, že môžete trochu zamerať v smere tehál, ktoré chcete \\\"paint\\\". Na úrovni 1, každá mince môže farba 1 tehly pred tým, ako je \\\"spent\\\" a zdá sa duté.\",\n    \"upgrades.minefield.name\": \"Minefield\",\n    \"upgrades.minefield.tooltip\": \"+{{percent}}% mincí za bombovú tehlu na obrazovke\",\n    \"upgrades.minefield.verbose_description\": \"Bomby sú počítané, zatiaľ čo sú explodujúce príliš.\",\n    \"upgrades.multiball.name\": \"Multi loptu\",\n    \"upgrades.multiball.tooltip\": \"Začnite všetky úrovne s {{count}} guľôčky.\",\n    \"upgrades.multiball.verbose_description\": \"Akonáhle spustíte loptu v Breakout 71, stratíte.\\n\\nS týmto atramentom získate dve guľôčky a môžete si dovoliť stratiť jeden.\\n\\nStratené gule sa vracajú na ďalšej úrovni.\\n\\nMať viac ako jednu guľôčku robí niektoré ďalšie perks k dispozícii, a samozrejme jasne vyrovnáva úroveň rýchlejšie.\",\n    \"upgrades.nbricks.name\": \"Prísne veľkosť vzorky\",\n    \"upgrades.nbricks.tooltip\": \"Viac mincí, ak narazíte na tehly jeden po druhom.\",\n    \"upgrades.nbricks.verbose_description\": \"\",\n    \"upgrades.one_more_choice.name\": \"Extra výber\",\n    \"upgrades.one_more_choice.tooltip\": \"Ďalšie možnosti upgradu\",\n    \"upgrades.one_more_choice.verbose_description\": \"Každý upgrade menu bude mať ešte jednu možnosť. Nezvyšuje počet upgradov si môžete vybrať.\",\n    \"upgrades.ottawa_treaty.name\": \"Ottawa zmluva\",\n    \"upgrades.ottawa_treaty.tooltip\": \"Breaking tehla v blízkosti bomby ho odzbrojuje\",\n    \"upgrades.ottawa_treaty.verbose_description\": \"Najbližšie bomba bude nahradená farebným blokom. Ak máte večeru, lopta uvoľní svoj šperk účinok až do ďalšieho odrazí. Iba jedna bomba môže byť nahradená naraz.\",\n    \"upgrades.paddle_up_combo.name\": \"\",\n    \"upgrades.paddle_up_combo.tooltip\": \"\",\n    \"upgrades.paddle_up_combo.verbose_description\": \"\",\n    \"upgrades.palette.name\": \"\",\n    \"upgrades.palette.tooltip\": \"\",\n    \"upgrades.palette.verbose_description\": \"\",\n    \"upgrades.passive_income.name\": \"Pasívny príjem\",\n    \"upgrades.passive_income.tooltip\": \"Viac mincí, ale pohyblivý paddleboard nezachytí guľôčky alebo mince\",\n    \"upgrades.passive_income.verbose_description\": \"+{{lvl}} combo / tehla rozbité, paddleboard je nemateriál {{time}}s po pohybe. Niektoré perks môže pomôcť guľôčky robiť to, čo chcete, bez toho, aby nič neurobil.\",\n    \"upgrades.picky_eater.name\": \"Picky jedér\",\n    \"upgrades.picky_eater.tooltip\": \"Viac mincí, ak zlomíte tehly farbu podľa farby\",\n    \"upgrades.picky_eater.verbose_description\": \"Vždy, keď rozbijete tehlu rovnakú farbu ako vaša lopta, vaše česano zvyšuje počet farieb na obrazovke mínus jeden.\\nAk je to iná farba, lopta trvá, že nová farba, ale hrebeňo resetuje, pokiaľ neboli žiadne tehly vľavo z farby lopty.\\nAkonáhle dostanete hrebeň vyššie ako vaše minimum, tehál nesprávnej farby dostane červenú hranicu.\\nAk máte viac ako jednu guľu, všetci prepínajú farbu, keď jeden z nich hity tehlu.\",\n    \"upgrades.pierce.name\": \"Piercing\",\n    \"upgrades.pierce.tooltip\": \"Loptové móly {{count}} tehly po páde paddle\",\n    \"upgrades.pierce.verbose_description\": \"Lopta zvyčajne odrazí hneď, ako sa niečo dotkne. S týmto atramentom bude pokračovať v jeho trajektórii až 3 tehly rozbité.\\n\\nPotom to bude odraziť na 4. tehál, a budete musieť dotknúť paddleboard resetovať pult.\",\n    \"upgrades.pierce_above_paddle.name\": \"\",\n    \"upgrades.pierce_above_paddle.tooltip\": \"\",\n    \"upgrades.pierce_above_paddle.verbose_description\": \"\",\n    \"upgrades.pierce_color.name\": \"Farba pierce\",\n    \"upgrades.pierce_color.tooltip\": \"Lopta prechádza tehálmi rovnakej farby\",\n    \"upgrades.pierce_color.verbose_description\": \"\",\n    \"upgrades.pierce_left.name\": \"\",\n    \"upgrades.pierce_left.tooltip\": \"\",\n    \"upgrades.pierce_left.verbose_description\": \"\",\n    \"upgrades.pierce_right.name\": \"\",\n    \"upgrades.pierce_right.tooltip\": \"\",\n    \"upgrades.pierce_right.verbose_description\": \"\",\n    \"upgrades.pierce_top.name\": \"\",\n    \"upgrades.pierce_top.tooltip\": \"\",\n    \"upgrades.pierce_top.verbose_description\": \"\",\n    \"upgrades.puck_repulse_ball.name\": \"Soft pristátie\",\n    \"upgrades.puck_repulse_ball.tooltip\": \"Paddle repulzné gule\",\n    \"upgrades.puck_repulse_ball.verbose_description\": \"Keď lopta dostane blízko k pádu, začne spomaliť, a dokonca potenciálne poskakovanie bez dotyku paddleboard.\",\n    \"upgrades.rainbow.name\": \"Dúha\",\n    \"upgrades.rainbow.tooltip\": \"Mince šité s dúha farba.\",\n    \"upgrades.rainbow.verbose_description\": \"Každá úroveň zvyšuje podiel farebných mincí. Farba závisí od času úrovne.\",\n    \"upgrades.reach.name\": \"Top dole\",\n    \"upgrades.reach.tooltip\": \"Viac mincí, ak sa vyhnete najnižšiemu rade tehál\",\n    \"upgrades.reach.verbose_description\": \"Dotykanie N tehál najnižšieho riadku resetuje hrebeň. V opačnom prípade +N combo.\\n\\nAk existuje len jeden rad tehál, alebo ak najnižšie rade tehál pokrývajú celú šírku hry, potom tento perk nemá nič. V opačnom prípade lámanie tohto najnižšieho riadku resetuje hrebeňo, zatiaľ čo lámanie niečo iného zvyšuje hrebeň podľa počtu tehál prítomných na tomto najnižšiom rade.\\n\\nNajnižší riadok bude zvýraznený červenou.\",\n    \"upgrades.refill.name\": \"\",\n    \"upgrades.refill.tooltip\": \"\",\n    \"upgrades.refill.verbose_description\": \"\",\n    \"upgrades.respawn.name\": \"Re-spawn\",\n    \"upgrades.respawn.tooltip\": \"{{percent}}% tehál re-spawn po {{delay}}s.\",\n    \"upgrades.respawn.verbose_description\": \"Niektorí účinok častíc vám umožní vedieť, kde sa objavia tehly.\",\n    \"upgrades.right_is_lava.name\": \"Vyhnite sa pravej strane\",\n    \"upgrades.right_is_lava.tooltip\": \"Viac mincí, ak sa nedotýkate pravej strane\",\n    \"upgrades.right_is_lava.verbose_description\": \"Kedykoľvek rozbijete tehál, váš hrebeň sa zvýši jeden, takže dostanete jednu viac mincí zo všetkých ďalších tehálov, ktoré zlomíte.\\n\\nAvšak, váš hrebeň bude resetovať hneď, ako vaša lopta hity na pravej strane.\\n\\nAkonáhle bude váš hrebeňo stúpa, správna strana sa červená, aby vám pripomenul, že by ste sa mali vyhnúť biť.\\n\\nNa úrovni 2 je hranica úplne odstránená a vaše guľôčky a mince by mohli stratiť.\",\n    \"upgrades.round_bricks.name\": \"\",\n    \"upgrades.round_bricks.tooltip\": \"\",\n    \"upgrades.round_bricks.verbose_description\": \"\",\n    \"upgrades.sacrifice.name\": \"Sacrifice\",\n    \"upgrades.sacrifice.tooltip\": \"\",\n    \"upgrades.sacrifice.verbose_description\": \"\",\n    \"upgrades.sapper.name\": \"Salón\",\n    \"upgrades.sapper.tooltip\": \"Prvá tehla zlomená sa stáva bombou.\",\n    \"upgrades.sapper.verbose_description\": \"Namiesto toho, aby len zmiznú, prvá tehla, ktorú zlomíte, bude nahradená bombovou tehálou. Porušenie lopty na paddleboard re-arms účinok. Úroveň-up tento perk vám umožní umiestniť viac bomby.\",\n    \"upgrades.shocks.name\": \"Shocks\",\n    \"upgrades.shocks.tooltip\": \"Zrážky výbušných guľôb\",\n    \"upgrades.shocks.verbose_description\": \"Vždy, keď dve guľôčky kolid, vymenia ich rýchlosť, prerezávajú výbuch, a získať pridané rýchlosť oddeliť ich.\",\n    \"upgrades.shunt.name\": \"SLOV\",\n    \"upgrades.shunt.tooltip\": \"Udržujte {{percent}}% vášho hrebeňa medzi úrovňami\",\n    \"upgrades.shunt.verbose_description\": \"Ak máte tiež horúci začiatok, horúci štart je len pridaný do aktuálneho hrebeňa\",\n    \"upgrades.side_flip.name\": \"Pravé odovzdané\",\n    \"upgrades.side_flip.tooltip\": \"\",\n    \"upgrades.side_flip.verbose_description\": \"\",\n    \"upgrades.side_kick.name\": \"Ľavá ruka\",\n    \"upgrades.side_kick.tooltip\": \"\",\n    \"upgrades.side_kick.verbose_description\": \"\",\n    \"upgrades.skip_last.name\": \"Jednoduché čistenie\",\n    \"upgrades.skip_last.tooltip\": \"Posledná tehla sa bude deštruktovať\",\n    \"upgrades.skip_last.verbose_description\": \"Musíte zlomiť všetky tehly ísť na ďalšiu úroveň. Avšak, to môže byť ťažké získať tie posledné.\\nKaždá úroveň tohto perka zvyšuje počet tehál, ktoré sa budú deštruktovať.\\nVymazanie úrovne čoskoro prináša ďalšie možnosti pri modernizácii. Nikdy chýba tehál je tiež veľmi prospešný.\\n\\nTakže ak zistíte, že je ťažké prelomiť posledné tehly, dostať tento perk niekoľko času môže pomôcť.\",\n    \"upgrades.slow_down.name\": \"Slower loptu\",\n    \"upgrades.slow_down.tooltip\": \"Lopta sa pohybuje viac pomaly\",\n    \"upgrades.slow_down.verbose_description\": \"Loptu začína relatívne pomalé, ale každá úroveň vašej hry začne trochu rýchlejšie.\\n\\nTo bude tiež urýchliť, ak trávite veľa času na jednej úrovni.\\n\\nTento perk to robí viac zvládnuteľný.\\n\\nMôžete ho získať na začiatku zakaždým tým, že umožní režim dieťaťa v menu.\",\n    \"upgrades.smaller_puck.name\": \"Malý paddleboard\",\n    \"upgrades.smaller_puck.tooltip\": \"{{percent}}% viac mincí\",\n    \"upgrades.smaller_puck.verbose_description\": \"To robí paddle menšie, čo v teórii robí niektoré rohové zábery jednoduchšie, ale naozaj len zvyšuje obtiažnosť.\\n\\nTo je dôvod, prečo si tiež získať pekný bonus +50% mince kúpele.\",\n    \"upgrades.soft_brush.name\": \"\",\n    \"upgrades.soft_brush.tooltip\": \"\",\n    \"upgrades.soft_brush.verbose_description\": \"\",\n    \"upgrades.soft_reset.name\": \"Soft reset\",\n    \"upgrades.soft_reset.tooltip\": \"Udržujte {{percent}}% vášho hrebeňa, keď sa obnoví\",\n    \"upgrades.soft_reset.verbose_description\": \"Obmedzte vplyv na obnovenie hrebeňa.\",\n    \"upgrades.soft_touch.name\": \"\",\n    \"upgrades.soft_touch.tooltip\": \"\",\n    \"upgrades.soft_touch.verbose_description\": \"\",\n    \"upgrades.steering.name\": \"Riadenie\",\n    \"upgrades.steering.tooltip\": \"Lopty zase pri páde\",\n    \"upgrades.steering.verbose_description\": \"Zmena paddleboardu priamo ovplyvňuje smer pohybu guľôčok. Na úrovni 2+, dostanete linku, ktorá vám ukazuje smer lopty.\",\n    \"upgrades.sticky_coins.name\": \"Nálepkové mince\",\n    \"upgrades.sticky_coins.tooltip\": \"Mince držať tehál rovnakej farby\",\n    \"upgrades.sticky_coins.verbose_description\": \"Na úrovni 2 sa držať tehál akejkoľvek farby\",\n    \"upgrades.streak_shots.name\": \"Hit streak\",\n    \"upgrades.streak_shots.tooltip\": \"Viac mincí, ak rozbijete veľa tehál naraz\",\n    \"upgrades.streak_shots.verbose_description\": \"Zakaždým, keď rozbijete tehlu, váš hrebeň sa zvyšuje jedným.\\n\\nAvšak, akonáhle lopta dotýka vaše paddleboard, hrebeňo je resetovať na svoju predvolenú hodnotu.\\n\\nPo tom, čo váš hrebeň stúpa nad základnou hodnotou, vaše paddleboard bude mať červenú hranicu, aby vám pripomenul, že to bude zničiť váš hrebeň, aby sa ho dotknúť s loptou.\",\n    \"upgrades.sturdy_bricks.name\": \"Sturdy tehly\",\n    \"upgrades.sturdy_bricks.tooltip\": \"+{{lvl}} tehly HP, +{{percent}}% mincí\",\n    \"upgrades.sturdy_bricks.verbose_description\": \"Každá úroveň tohto perka pridáva jeden HP na všetky tehly. Môžete vidieť číslo HP s \\\"clairvoyant\\\" perk. Môžete zvýšiť poškodenie lopty tým, že dostanete \\\"piercing\\\" perk. Každá úroveň perk pridáva +50% mince kúpele.\",\n    \"upgrades.superhot.name\": \"SUPER HOT\",\n    \"upgrades.superhot.tooltip\": \"Čas sa pohybuje, keď sa paddleboard pohybuje.\",\n    \"upgrades.superhot.verbose_description\": \"SUPER HOT SUPER HOT SUPER HOT SUPER HOT\",\n    \"upgrades.telekinesis.name\": \"Telekinéza\",\n    \"upgrades.telekinesis.tooltip\": \"Poschodová poloha ovplyvňuje loptu\",\n    \"upgrades.telekinesis.verbose_description\": \"Ovládate loptu, zatiaľ čo to bude hore. Účinok je silnejší, keď je lopta v spodnej polovici obrazovky.\",\n    \"upgrades.thomas.name\": \"\",\n    \"upgrades.thomas.tooltip\": \"\",\n    \"upgrades.thomas.verbose_description\": \"\",\n    \"upgrades.three_cushion.name\": \"Tri vankúš\",\n    \"upgrades.three_cushion.tooltip\": \"Viac mincí, ak narazíte na tehly iba nepriamo\",\n    \"upgrades.three_cushion.verbose_description\": \"\",\n    \"upgrades.top_is_lava.name\": \"Sky je limit\",\n    \"upgrades.top_is_lava.tooltip\": \"Viac mincí, ak sa vyhnete biť hore\",\n    \"upgrades.top_is_lava.verbose_description\": \"Kedykoľvek rozbijete tehál, váš hrebeň sa zvýši jeden. Avšak, vaše combo bude resetovať hneď, ako vaša lopta hit vrchol obrazovky.\\n\\nKeď je váš hrebeň nad minimum, sa objaví červený bar na vrchole, aby vám pripomenul, že by ste sa mali vyhnúť biť.\\n\\nNa úrovni 2 je hranica úplne odstránená a vaše guľôčky a mince by mohli stratiť.\",\n    \"upgrades.trampoline.name\": \"Trampoline\",\n    \"upgrades.trampoline.tooltip\": \"Viac mincí, ak odrazíte na tehly a paddleboard iba\",\n    \"upgrades.trampoline.verbose_description\": \"+{{lvl}} combo na pád,-{{lvl}} combo na každom okraji. Jeden z vzácnych hrebeňov, ktoré nepridávajú stav obnovenia\",\n    \"upgrades.transparency.name\": \"Aktuality\",\n    \"upgrades.transparency.tooltip\": \"+50% mincí. Lopta je neviditeľný v hornej časti obrazovky.\",\n    \"upgrades.transparency.verbose_description\": \"Lopta sa stáva transparentnou v hornej časti obrazovky.\\n+{{percent}} % mincí.\\nVyššie úrovne, aby lopta priehľadný skôr a zvýšiť bod bonus.\",\n    \"upgrades.trickledown.name\": \"Triky dole\",\n    \"upgrades.trickledown.tooltip\": \"Mince sa objavujú v hornej časti obrazovky.\",\n    \"upgrades.trickledown.verbose_description\": \"Mince by mohli sedieť na vrchole tehly, ak sú tehly na hornom riadku, v takom prípade sa po rozpade, že tehla.\",\n    \"upgrades.unbounded.name\": \"Zváranie\",\n    \"upgrades.unbounded.tooltip\": \"Dodáva priestor vľavo a vpravo od úrovne, ale vaša paddleboard nemôže ísť tak ďaleko.\",\n    \"upgrades.unbounded.verbose_description\": \"Ďalšou upgradu vám môže pomôcť predĺžiť dosah paddleboardu.\",\n    \"upgrades.varied_diet.name\": \"\",\n    \"upgrades.varied_diet.tooltip\": \"\",\n    \"upgrades.varied_diet.verbose_description\": \"\",\n    \"upgrades.vibrant_neighborhood.name\": \"\",\n    \"upgrades.vibrant_neighborhood.tooltip\": \"\",\n    \"upgrades.vibrant_neighborhood.verbose_description\": \"\",\n    \"upgrades.viscosity.name\": \"Viskozita\",\n    \"upgrades.viscosity.tooltip\": \"Spomalenie mince\",\n    \"upgrades.viscosity.verbose_description\": \"Mince zvyčajne urýchľujú gravitáciu a výbuchy na pomerne vysoké rýchlosti.\\n\\nTento perk ich neustále spomaľuje, ako keby boli v niektorých typoch viskozity kvapaliny.\\n\\nTo ich chytí jednoduchšie a kombinuje pekne s perks, ktoré ovplyvňujú pohyb mince.\",\n    \"upgrades.wind.name\": \"Vietor\",\n    \"upgrades.wind.tooltip\": \"Poschodová poloha vytvára vietor\",\n    \"upgrades.wind.verbose_description\": \"Vietor závisí od polohy pádu: ľavé údery vľavo, vpravo fúka. Ovplyvňuje guľôčky a mince.\",\n    \"upgrades.wrap_left.name\": \"Balenie vľavo\",\n    \"upgrades.wrap_left.tooltip\": \"Narazil na ľavej strane teleports loptu na pravej strane\",\n    \"upgrades.wrap_left.verbose_description\": \"Vyššie úrovne teleportové mince tiež.\",\n    \"upgrades.wrap_right.name\": \"Zabaliť právo\",\n    \"upgrades.wrap_right.tooltip\": \"Narazil na pravej strane teleports loptu na ľavej strane\",\n    \"upgrades.wrap_right.verbose_description\": \"Vyššie úrovne teleportové mince tiež.\",\n    \"upgrades.wrap_up.name\": \"Zabaliť hore\",\n    \"upgrades.wrap_up.tooltip\": \"Dotykanie hornej obrazovky bude teleport loptu tesne nad pádom.\",\n    \"upgrades.wrap_up.verbose_description\": \"To nebude počítať ako pád paddleboard. Na úrovni 2, mince teleport tiež.\",\n    \"upgrades.yoyo.name\": \"Yo-yo\",\n    \"upgrades.yoyo.tooltip\": \"Lopta padá smerom k pádu\",\n    \"upgrades.yoyo.verbose_description\": \"Je to opak telekinézy, ovládať loptu, zatiaľ čo to padá späť.\",\n    \"upgrades.zen.name\": \"Slovenčina\",\n    \"upgrades.zen.tooltip\": \"Viac mincí, ak nechcete spúšťať bomby\",\n    \"upgrades.zen.verbose_description\": \"+{{lvl}} combo každý 3s, reset, keď je výbuch\"\n}\n","{\n    \"confirmRestart.no\": \"Anulare\",\n    \"confirmRestart.text\": \"\",\n    \"confirmRestart.title\": \"Începi un joc nou?\",\n    \"confirmRestart.yes\": \"Reîncepe jocul\",\n    \"editor.editing.author\": \"\",\n    \"editor.editing.author_prompt\": \"\",\n    \"editor.editing.author_required\": \"\",\n    \"editor.editing.bigger\": \"Crește mărimea nivelului\",\n    \"editor.editing.category\": \"\",\n    \"editor.editing.category_prompt\": \"\",\n    \"editor.editing.color\": \"Alege o coloare dintr-o listă (maxim 5 pe fiecare nivel)\",\n    \"editor.editing.copied\": \"\",\n    \"editor.editing.copy\": \"\",\n    \"editor.editing.copy_help\": \"\",\n    \"editor.editing.credit\": \"\",\n    \"editor.editing.credit_prompt\": \"\",\n    \"editor.editing.delete\": \"\",\n    \"editor.editing.delete_confirm\": \"\",\n    \"editor.editing.delete_no\": \"\",\n    \"editor.editing.delete_yes\": \"\",\n    \"editor.editing.down\": \"\",\n    \"editor.editing.help\": \"\",\n    \"editor.editing.left\": \"\",\n    \"editor.editing.play\": \"\",\n    \"editor.editing.rename\": \"\",\n    \"editor.editing.rename_prompt\": \"\",\n    \"editor.editing.right\": \"\",\n    \"editor.editing.show_code\": \"\",\n    \"editor.editing.show_code_help\": \"\",\n    \"editor.editing.smaller\": \"\",\n    \"editor.editing.title\": \"\",\n    \"editor.editing.up\": \"\",\n    \"editor.help\": \"\",\n    \"editor.import\": \"\",\n    \"editor.import_instruction\": \"\",\n    \"editor.leave_preview\": \"\",\n    \"editor.new_level\": \"\",\n    \"editor.title\": \"Editor de nivel\",\n    \"gameOver.creative\